import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] poly = new int[10];
        for (int i = 0; i < k; ++i) poly[in.nextInt()] = 1;
        int[] result = {1};
        int p = n >> 1;
        while (p != 0) {
            if ((p & 1) == 1) result = multiply(result, poly, MOD);
            p >>= 1;
            if (p != 0) poly = multiply(poly, poly, MOD);
        }
        long ans = 0;
        for (int x : result) ans = (ans + (long) x * x) % MOD;
        out.println((int) ans);
        out.close();
    }

    static int[] multiply(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);
        double[] aRe = new double[n], aIm = new double[n];
        for (int i = 0; i < a.length; ++i) {
            int x = (a[i] % mod + mod) % mod;
            aRe[i] = x & 0x7FFF;
            aIm[i] = x >> 15;
        }
        fft(aRe, aIm, false);

        double[] bRe = new double[n], bIm = new double[n];
        if (a == b) {
            System.arraycopy(aRe, 0, bRe, 0, n);
            System.arraycopy(aIm, 0, bIm, 0, n);
        } else {
            for (int i = 0; i < b.length; ++i) {
                int x = (b[i] % mod + mod) % mod;
                bRe[i] = x & 0x7FFF;
                bIm[i] = x >> 15;
            }
            fft(bRe, bIm, false);
        }

        double[] fRe = new double[n], fIm = new double[n];
        double[] gRe = new double[n], gIm = new double[n];
        double factor = 0.25 / n;
        for (int i = 0; i < n; ++i) {
            int j = (n - i) & (n - 1);
            double a1r = aRe[i] + aRe[j];
            double a1i = aIm[i] - aIm[j];
            double a2r = aIm[i] + aIm[j];
            double a2i = aRe[j] - aRe[i];
            double b1r = (bRe[i] + bRe[j]) * factor;
            double b1i = (bIm[i] - bIm[j]) * factor;
            double b2r = (bIm[i] + bIm[j]) * factor;
            double b2i = (bRe[j] - bRe[i]) * factor;
            fRe[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            fIm[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            gRe[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            gIm[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(fRe, fIm, true);
        fft(gRe, gIm, true);
        int[] res = new int[need];
        for (int i = 0; i < need; ++i) {
            long x = (long) (fRe[i] + 0.5);
            long y = (long) (gRe[i] + 0.5);
            long z = (long) (fIm[i] + 0.5);
            res[i] = (int) ((x + ((y % mod) << 15) + ((z % mod) << 30)) % mod);
        }
        return res;
    }

    static void fft(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int shift = 32 - Integer.numberOfTrailingZeros(n);
        for (int i = 1; i < n; ++i) {
            int j = Integer.reverse(i << shift);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cos = new double[half];
            double[] sin = new double[half];
            for (int i = 0; i < half; ++i) {
                cos[i] = Math.cos(2 * Math.PI * i / len * (inverse ? -1 : 1));
                sin[i] = Math.sin(2 * Math.PI * i / len * (inverse ? -1 : 1));
            }
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; ++j) {
                    double uR = re[i + j];
                    double uI = im[i + j];
                    double vR = re[i + j + half] * cos[j] - im[i + j + half] * sin[j];
                    double vI = re[i + j + half] * sin[j] + im[i + j + half] * cos[j];
                    re[i + j] = uR + vR;
                    im[i + j] = uI + vI;
                    re[i + j + half] = uR - vR;
                    im[i + j + half] = uI - vI;
                }
            }
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c))
                c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1)
                throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0)
                    return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
